 tb(['Change', 'Detail'], ['Giving a bribe', 'categorically an <b>offence</b>; in <b>coercive corruption</b>, a person who complains within <b>7 days</b> of the offence is <b>not considered guilty</b>'], ['Sec 17A', 'extended to <b>retired</b> civil servants: sanction of the appropriate authority is needed to act against them too'], ['Sec 13(1)(d)', 'originally a public servant could be prosecuted for a decision that benefits a commercial organisation and violates public interest; this was <b>diluted</b>'], ['Jail; trial', 'jail time <b>increased from 3 years to 7 years</b> (handout wording); trial to finish in <b>2 years, up to a maximum of 4</b>'], ['Commercial activity; property', 'provisions for <b>prosecution of commercial activities</b> and for <b>attachment or confiscation</b> of property']),
